compile.workshop:
variables {
    global:
        0: g
}

rule ("numeric literal in a Team position") {
    event {
        Ongoing - Each Player;
        Team 2;
        All;
    }
    actions {
        Set Global Variable(g, All Living Players(2));
        Set Team Score(2, 5);
    }
}

